import pygame
import sys
import random

# Initialize Pygame
pygame.init()

# Constants
SCREEN_WIDTH = 400
SCREEN_HEIGHT = 400
GRID_SIZE = 4
CELL_SIZE = SCREEN_WIDTH // GRID_SIZE
FPS = 60

# Colors
WHITE = (255, 255, 255)
BLACK = (0, 0, 0)
GRAY = (185, 175, 165)

# Initialize the screen
screen = pygame.display.set_mode((SCREEN_WIDTH, SCREEN_HEIGHT))
pygame.display.set_caption('2048 Game')

# Initialize the game board
board = [[0] * GRID_SIZE for _ in range(GRID_SIZE)]

# Function to draw the grid
def draw_grid():
    for row in range(GRID_SIZE):
        for col in range(GRID_SIZE):
            value = board[row][col]
            if value != 0:
                text = pygame.font.SysFont(None, 40).render(str(value), True, BLACK)
                screen.blit(text, (col * CELL_SIZE + 15, row * CELL_SIZE + 15))
            else:
                pygame.draw.rect(screen, GRAY, (col * CELL_SIZE, row * CELL_SIZE, CELL_SIZE, CELL_SIZE), 2)

# Function to add a new number to the board
def add_new_number():
    empty_cells = [(row, col) for row in range(GRID_SIZE) for col in range(GRID_SIZE) if board[row][col] == 0]
    if empty_cells:
        row, col = empty_cells[0]
        board[row][col] = 2 if random.random() < 0.9 else 4

# Function to move tiles in a given direction
def move_tiles(direction):
    if direction == 'up':
        for col in range(GRID_SIZE):
            for row in range(1, GRID_SIZE):
                if board[row][col] != 0:
                    r = row
                    while r > 0 and board[r-1][col] == 0:
                        board[r-1][col], board[r][col] = board[r][col], board[r-1][col]
                        r -= 1
                    if r > 0 and board[r-1][col] == board[r][col]:
                        board[r-1][col] *= 2
                        board[r][col] = 0
    elif direction == 'down':
        for col in range(GRID_SIZE):
            for row in range(GRID_SIZE-2, -1, -1):
                if board[row][col] != 0:
                    r = row
                    while r < GRID_SIZE-1 and board[r+1][col] == 0:
                        board[r+1][col], board[r][col] = board[r][col], board[r+1][col]
                        r += 1
                    if r < GRID_SIZE-1 and board[r+1][col] == board[r][col]:
                        board[r+1][col] *= 2
                        board[r][col] = 0
    elif direction == 'left':
        for row in range(GRID_SIZE):
            for col in range(1, GRID_SIZE):
                if board[row][col] != 0:
                    c = col
                    while c > 0 and board[row][c-1] == 0:
                        board[row][c-1], board[row][c] = board[row][c], board[row][c-1]
                        c -= 1
                    if c > 0 and board[row][c-1] == board[row][c]:
                        board[row][c-1] *= 2
                        board[row][c] = 0
    elif direction == 'right':
        for row in range(GRID_SIZE):
            for col in range(GRID_SIZE-2, -1, -1):
                if board[row][col] != 0:
                    c = col
                    while c < GRID_SIZE-1 and board[row][c+1] == 0:
                        board[row][c+1], board[row][c] = board[row][c], board[row][c+1]
                        c += 1
                    if c < GRID_SIZE-1 and board[row][c+1] == board[row][c]:
                        board[row][c+1] *= 2
                        board[row][c] = 0

# Main game loop
def main():
    clock = pygame.time.Clock()
    add_new_number()
    add_new_number()

    while True:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            elif event.type == pygame.KEYDOWN:
                moved = False
                if event.key == pygame.K_UP:
                    move_tiles('up')
                    moved = True
                elif event.key == pygame.K_DOWN:
                    move_tiles('down')
                    moved = True
                elif event.key == pygame.K_LEFT:
                    move_tiles('left')
                    moved = True
                elif event.key == pygame.K_RIGHT:
                    move_tiles('right')
                    moved = True
                if moved:
                    add_new_number()

        screen.fill(WHITE)
        draw_grid()
        pygame.display.flip()
        clock.tick(FPS)

if __name__ == "__main__":
    main()

