def _legacy_mergeOrderings(orderings: List[List[Any]]) -> List[Any]:
    """
    Combine multiple lists in the sequence of occurrence into a list with no duplicate elements.
    """
    result = []
    for order in orderings:
        for item in order:
            if item not in result:
                result.append(item)
    return result

