from typing import List
import platform

def cmd_split(s: str) -> List[str]:
    """
    Splits a string according to the Windows/CMD style.
    """
    return s.split(' ')

def posix_split(s: str) -> List[str]:
    """
    Splits a string according to the POSIX style.
    """
    return s.split(' ')

def split(s: str, platform: str = 'this') -> List[str]:
    """
    Splits a string based on the specified platform.

    Args:
        s (str): The input string to be split.
        platform (str): The platform style ('this', 'cmd', 'posix').

    Returns:
        List[str]: A list of split strings.
    """
    if platform == 'this':
        current_platform = platform.system().lower()
        if current_platform == 'windows':
            return cmd_split(s)
        else:
            return posix_split(s)
    elif platform == 'cmd':
        return cmd_split(s)
    elif platform == 'posix':
        return posix_split(s)
    else:
        raise ValueError("Invalid platform specified. Use 'this', 'cmd', or 'posix'.")

# Example usage:
# result = split("Hello World", platform="cmd")
# print(result)  # Output: ['Hello', 'World']

